def check_armor_compatibility_for_class(class_key, item_info):
    slot_key = str((item_info or {}).get("slot_key") or "")
    if slot_key not in {"helmet", "shoulders", "chest", "gloves", "legs", "boots"}:
        return _compat_result(True)
    armor_type = str((item_info or {}).get("armor_type") or "")
    allowed = str(ARMOR_ALLOWED_BY_CLASS.get(class_key) or "")
    if not armor_type or armor_type == allowed:
        return _compat_result(True)
    return _compat_result(False, "❌ Цей тип броні не підходить твоєму класу.")

def check_main_hand_compatibility_for_class(class_key, item_info):
    if str((item_info or {}).get("slot_key") or "") != "main_hand":
        return _compat_result(True)
    subtype = str((item_info or {}).get("item_subtype") or "")
    if subtype in set(MAIN_HAND_ALLOWED_BY_CLASS.get(class_key) or []):
        return _compat_result(True)
    return _compat_result(False, "❌ Ця зброя не підходить твоєму класу.")

def check_off_hand_compatibility_for_class(class_key, item_info):
    if str((item_info or {}).get("slot_key") or "") != "off_hand":
        return _compat_result(True)
    subtype = str((item_info or {}).get("item_subtype") or "")
    if subtype in set(OFF_HAND_ALLOWED_BY_CLASS.get(class_key) or []):
        return _compat_result(True)
    return _compat_result(False, "❌ Цей предмет для другої руки не підходить твоєму класу.")

def check_two_handed_conflict_for_equip(user_id, item_info):
    slot_key = str((item_info or {}).get("slot_key") or "")
    if slot_key != "off_hand":
        return _compat_result(True)
    rows = get_all_equipped_slots(user_id) or {}
    main_hand = rows.get("main_hand") if isinstance(rows, dict) else None
    if not main_hand:
        return _compat_result(True)
    try:
        main_info = get_item_classification_by_inventory_id(int(main_hand)) or {}
    except Exception:
        main_info = {}
    if int(main_info.get("weapon_hands") or 1) == 2:
        return _compat_result(False, "❌ Неможливо: дворучна зброя блокує другу руку")
    return _compat_result(True)

def _class_aware_equipment_kind(slot_key):
    if slot_key == "main_hand":
        return "weapon"
    if slot_key == "off_hand":
        return "off_hand"
    if slot_key in ("necklace", "ring"):
        return "jewelry"
    return "armor"

def _class_aware_weighted_choice(profile):
    return random.choices(
        [stat for stat, _weight in profile],
        weights=[weight for _stat, weight in profile],
        k=1,
    )[0]

def get_bag_capacity(user_id):
    cursor.execute("""
    SELECT bag_slots
    FROM users
    WHERE user_id=?
    """, (user_id,))

    row = cursor.fetchone()

    if not row or row[0] is None:
        return DEFAULT_BAG_SLOTS

    try:
        capacity = int(row[0] or DEFAULT_BAG_SLOTS)
    except Exception:
        capacity = DEFAULT_BAG_SLOTS
    return max(DEFAULT_BAG_SLOTS, capacity)

def get_dynamic_stat_value(item_level, rarity, base=1.0):
    multiplier = DYNAMIC_STAT_MULTIPLIERS.get(rarity, 1.0)
    value = int(round(item_level * base * multiplier))

    return max(1, value)

def get_dynamic_sell_price(item_level, rarity):
    multiplier = DYNAMIC_SELL_MULTIPLIERS.get(rarity, 0.30)

    return round(max(0.10, item_level * multiplier), 2)

def init_dynamic_equipment_system():
    migrations = [
        ("items", "item_level", "INTEGER DEFAULT 1"),
        ("items", "is_generated", "INTEGER DEFAULT 0"),
        ("items", "item_subtype", "TEXT DEFAULT ''"),
    ]

    for table, column, column_type in migrations:
        try:
            cursor.execute(f"ALTER TABLE {table} ADD COLUMN {column} {column_type}")
        except Exception:
            pass

    conn.commit()

def add_stat_value(stats, stat_key, value):
    if stat_key == "str":
        stats["bonus_str"] += value
    elif stat_key == "dex":
        stats["bonus_dex"] += value
    elif stat_key == "int":
        stats["bonus_int"] += value
    elif stat_key == "wis":
        stats["bonus_wis"] += value
    elif stat_key == "sta":
        stats["bonus_sta"] += value

def get_profile_for_generated_item(slot_key, item_profile=None):
    if slot_key == "main_hand":
        if item_profile in MAIN_HAND_PROFILES:
            return item_profile

        return get_random_main_hand_profile()

    if slot_key == "off_hand":
        if item_profile in OFF_HAND_PROFILES:
            return item_profile

        return get_random_off_hand_profile()

    return ""

def init_class_equipment_restrictions_system():
    """
    Додає службове поле armor_type для класових обмежень броні.

    weapon_family окремо НЕ додаємо.
    У поточній системі роль weapon_family виконує items.item_subtype.
    """

    migrations = [
        ("items", "armor_type", "TEXT DEFAULT ''"),
    ]

    for table, column, column_type in migrations:
        try:
            cursor.execute(f"ALTER TABLE {table} ADD COLUMN {column} {column_type}")
        except Exception:
            pass

    conn.commit()

def normalize_equipment_restriction_value(value):
    if value is None:
        return ""

    return str(value).strip()

def pick_weighted_stat(weighted_stats, exclude_stat=None):
    """
    Вибирає характеристику за вагами.
    """

    filtered = []

    for stat_key, weight in weighted_stats:
        if exclude_stat is not None and stat_key == exclude_stat:
            continue

        filtered.append((stat_key, weight))

    if not filtered:
        filtered = weighted_stats

    if not filtered:
        return ""

    total_weight = sum(weight for _, weight in filtered)

    if total_weight <= 0:
        return filtered[0][0]

    roll = random.randint(1, total_weight)
    current = 0

    for stat_key, weight in filtered:
        current += weight

        if roll <= current:
            return stat_key

    return filtered[-1][0]

def add_primary_stat_to_stats(stats, stat_key, value):
    """
    Додає основну характеристику у stats.
    """

    value = int(value or 0)

    if value <= 0:
        return

    if stat_key == "str":
        stats["bonus_str"] += value

    elif stat_key == "dex":
        stats["bonus_dex"] += value

    elif stat_key == "int":
        stats["bonus_int"] += value

    elif stat_key == "wis":
        stats["bonus_wis"] += value

    elif stat_key == "sta":
        stats["bonus_sta"] += value

def get_random_class_aware_equipment_choice(user_id):
    """
    Повертає slot_key, item_profile, armor_type для предмета під клас.

    Логіка:
    - броня під клас;
    - main_hand під клас;
    - off_hand під клас, якщо клас має дозволений off_hand.
    """

    class_key = get_character_class(user_id)

    allowed_armor_type = get_allowed_armor_type_for_class(class_key)
    allowed_main_hand = get_allowed_main_hand_subtypes_for_class(class_key)
    allowed_off_hand = get_allowed_off_hand_subtypes_for_class(class_key)

    has_off_hand = len(allowed_off_hand) > 0

    roll = random.random()

    # Якщо клас має off-hand:
    # 60% броня, 25% main hand, 15% off hand.
    if has_off_hand:
        if roll < 0.60:
            return {
                "slot_key": random.choice(ARMOR_SLOTS),
                "item_profile": "",
                "armor_type": allowed_armor_type
            }

        if roll < 0.85:
            return {
                "slot_key": "main_hand",
                "item_profile": random.choice(allowed_main_hand),
                "armor_type": ""
            }

        return {
            "slot_key": "off_hand",
            "item_profile": random.choice(allowed_off_hand),
            "armor_type": ""
        }

    # Якщо клас НЕ має off-hand:
    # 65% броня, 35% main hand.
    if roll < 0.65:
        return {
            "slot_key": random.choice(ARMOR_SLOTS),
            "item_profile": "",
            "armor_type": allowed_armor_type
        }

    return {
        "slot_key": "main_hand",
        "item_profile": random.choice(allowed_main_hand),
        "armor_type": ""
    }

