    if isinstance(preview, dict) and not preview.get("success", True):

        return preview

    if isinstance(preview, dict):

        preview_id = preview.get("item_id") or preview.get("preview_item_id") or preview.get("id")

    else:

        preview_id = preview

    if not preview_id:

        return {"success": False, "message": "❌ Не вдалося створити товар магазину."}

    return confirm_preview(uid, int(preview_id))

def _catalog_row(item):
    return (
        int(item["id"]), str(item["name"]), str(item["type"]),
        str(item["rarity"]), str(item["category"]), None, 1,
        int(item["max_stack"]), float(item.get("sell_price", 0.0)),
        0, 0, 0, 0, 0, 0, 0,
    )

def validate_event_item_catalog_definitions(definitions=None):
    items = get_registered_event_item_definitions() if definitions is None else tuple(definitions)
    seen = set()
    for item in items:
        item_id = int(item["id"])
        if item_id in seen:
            raise ValueError("duplicate event item ID")
        seen.add(item_id)
        if not str(item.get("name") or "").strip():
            raise ValueError("event item name is required")
        if int(item.get("max_stack") or 0) <= 0:
            raise ValueError("event item max_stack must be positive")
        for flag in ("tradeable", "sellable", "auctionable"):
            if item.get(flag) is not False:
                raise ValueError(f"pilot item must explicitly set {flag}=False")
        if float(item.get("sell_price", 0.0)) != 0.0:
            raise ValueError("pilot item sell_price must be zero")
    return items

def seed_event_item_catalog(connection=None, *, commit=True):
    if connection is None:
        from db_modules.connection import conn as connection
    definitions = validate_event_item_catalog_definitions()
    sql = """
        INSERT INTO items (
            id,name,type,rarity,category,slot_key,weapon_hands,max_stack,sell_price,
            bonus_str,bonus_dex,bonus_int,bonus_wis,bonus_sta,pdef,mdef
        ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        ON CONFLICT(id) DO UPDATE SET
            name=excluded.name,type=excluded.type,rarity=excluded.rarity,
            category=excluded.category,slot_key=excluded.slot_key,
            weapon_hands=excluded.weapon_hands,max_stack=excluded.max_stack,
            sell_price=excluded.sell_price,bonus_str=excluded.bonus_str,
            bonus_dex=excluded.bonus_dex,bonus_int=excluded.bonus_int,
            bonus_wis=excluded.bonus_wis,bonus_sta=excluded.bonus_sta,
            pdef=excluded.pdef,mdef=excluded.mdef
    """
    rows = tuple(_catalog_row(item) for item in definitions)
    try:
        for row in rows:
            connection.execute(sql, row)
        if commit:
            connection.commit()
    except Exception:
        if commit:
            connection.rollback()
        raise
    return {"success": True, "seeded": len(rows), "item_ids": tuple(row[0] for row in rows)}

def init_item_id_allocator_system(db_path=None, conn=None):
    own=conn is None
    if own: conn=sqlite3.connect(db_path or "game.db")
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS item_id_allocator(
            namespace TEXT PRIMARY KEY,last_issued_id INTEGER NOT NULL,
            range_min INTEGER NOT NULL,range_max INTEGER NOT NULL,
            updated_at TEXT NOT NULL)""")
        conn.execute("""CREATE TABLE IF NOT EXISTS generated_item_id_migrations(
            id INTEGER PRIMARY KEY AUTOINCREMENT,source_item_id INTEGER NOT NULL,
            target_item_id INTEGER NOT NULL UNIQUE,operation TEXT NOT NULL,
            migration_stage TEXT NOT NULL,created_at TEXT NOT NULL,
            UNIQUE(source_item_id,target_item_id,operation))""")
        now=datetime.now(timezone.utc).isoformat()
        permanent_max=conn.execute("SELECT COALESCE(MAX(id),?) FROM items WHERE is_generated=1 AND shop_preview_owner IS NULL AND COALESCE(shop_preview_price,0)=0 AND id BETWEEN ? AND ?",(PRIMARY_MIN-1,PRIMARY_MIN,OVERFLOW_MAX)).fetchone()[0]
        preview_max=conn.execute("SELECT COALESCE(MAX(id),?) FROM items WHERE (shop_preview_owner IS NOT NULL OR COALESCE(shop_preview_price,0)>0) AND id BETWEEN ? AND ?",(PREVIEW_MIN-1,PREVIEW_MIN,PREVIEW_MAX)).fetchone()[0]
        conn.execute("INSERT OR IGNORE INTO item_id_allocator(namespace,last_issued_id,range_min,range_max,updated_at) VALUES(?,?,?,?,?)",(PERMANENT_NAMESPACE,max(PRIMARY_MIN-1,int(permanent_max)),PRIMARY_MIN,OVERFLOW_MAX,now))
        conn.execute("INSERT OR IGNORE INTO item_id_allocator(namespace,last_issued_id,range_min,range_max,updated_at) VALUES(?,?,?,?,?)",(PREVIEW_NAMESPACE,max(PREVIEW_MIN-1,int(preview_max)),PREVIEW_MIN,PREVIEW_MAX,now))
        if own: conn.commit()
        return {"success":True}
    finally:
        if own: conn.close()

def _allocate(conn,namespace):
    init_item_id_allocator_system(conn=conn)
    row=conn.execute("SELECT last_issued_id,range_min,range_max FROM item_id_allocator WHERE namespace=?",(namespace,)).fetchone()
    if not row: raise RuntimeError("Allocator namespace is not initialized")
    next_id=max(int(row[0])+1,int(row[1]))
    if next_id>int(row[2]): raise ItemIdPoolExhausted(f"Item ID pool exhausted: {namespace}")
    if conn.execute("SELECT 1 FROM items WHERE id=?",(next_id,)).fetchone(): raise RuntimeError(f"Allocator collision at {next_id}")
    conn.execute("UPDATE item_id_allocator SET last_issued_id=?,updated_at=? WHERE namespace=?",(next_id,datetime.now(timezone.utc).isoformat(),namespace))
    return next_id

