                ),
            )
        conn.commit()
        updated.update({"status": status, "expires_at": expires})
        return {
            "success": True,
            "trade": updated,
            "both_ready": status == "confirming",
            "changed": changed,
        }
    except Exception:
        conn.rollback()
        raise
    finally:
